/// The block's property shape (property ids into `BLOCK_PROPERTY_VALUES`, in
/// declaration order), or `&[]` for a single-state block.
pub fn shape_of(block: BlockId) -> &'static [u16] {
    match BLOCK_STATE_SHAPES.binary_search_by_key(&block.0, |(b, _)| *b) {
        Ok(i) => BLOCK_STATE_SHAPES[i].1,
        Err(_) => &[],
    }
}

/// Forward: block + property value indices (in the block's declaration order) ->
/// dense global id. `values.len()` must equal `shape_of(block).len()`, and each
/// value must be < its property's value count (a corrupt index would otherwise
/// silently compose an out-of-range id in release).
pub fn state_id(block: BlockId, values: &[u16]) -> StateId {
    let shape = shape_of(block);
    debug_assert_eq!(values.len(), shape.len());
    let base = BLOCK_STATE_BASES[block.0 as usize].base;
    // Mixed-radix over the shape, last property varying fastest (stride 1).
    let mut local = 0u16;
    let mut stride = 1u16;
    for (value, prop) in values.iter().zip(shape.iter()).rev() {
        local += *value * stride;
        stride *= BLOCK_PROPERTY_VALUES[*prop as usize].len() as u16;
    }
    // Every in-range digit keeps `local < count` (mixed-radix bound); a value
    // index >= its property's value count is a caller bug, caught in debug.
    debug_assert!(local < BLOCK_STATE_BASES[block.0 as usize].count);
    StateId(base + local)
}

/// Reverse: global id -> block. Ids outside `0..BLOCK_STATE_COUNT` fall back to air
/// (block 0, state 0), mirroring `Block.stateById` / the global palette's
/// missing-id behaviour.
pub fn block_of(id: StateId) -> BlockId {
    let id = id.0 as u32;
    // Last block whose base is <= id (bases are strictly increasing).
    let idx = BLOCK_STATE_BASES.partition_point(|b| b.base as u32 <= id);
    if idx == 0 {
        return BlockId(0);
    }
    let b = &BLOCK_STATE_BASES[idx - 1];
    if id < b.base as u32 + b.count as u32 {
        BlockId((idx - 1) as u16)
    } else {
        BlockId(0)
    }
}

/// Reverse: global id -> the owning block's property value indices, written in the
/// block's declaration order. `out.len()` must be at least `shape_of(block).len()`.
pub fn values_of(id: StateId, out: &mut [u16]) {
    let block = block_of(id);
    let shape = shape_of(block);
    debug_assert!(out.len() >= shape.len());
    let mut local = id.0 - BLOCK_STATE_BASES[block.0 as usize].base;
    for (i, prop) in shape.iter().enumerate().rev() {
        let size = BLOCK_PROPERTY_VALUES[*prop as usize].len() as u16;
        out[i] = local % size;
        local /= size;
    }
}

/// The block's default state (the report's `default` marker).
pub fn default_state(block: BlockId) -> StateId {
    StateId(BLOCK_STATE_BASES[block.0 as usize].default)
}

/// Whether `id` names a real block state (`id < BLOCK_STATE_COUNT`).
pub fn is_valid(id: StateId) -> bool {
    id.0 < BLOCK_STATE_COUNT
}
